function getWarlockProgression(level) {
  const lvl = Math.min(20, Math.max(1, Number(level) || 6));
  const rule = WARLOCK_LEVEL_RULES[lvl];
  const smiteDice = `${1 + rule.slotLevel}d8`;
  const eldritchBeams = lvl < 5 ? 1 : (lvl < 11 ? 2 : (lvl < 17 ? 3 : 4));
  const cantripDiceCount = lvl < 5 ? 1 : (lvl < 11 ? 2 : (lvl < 17 ? 3 : 4));
  const agathysHP = rule.slotLevel * 5;
  const spectreTempHP = Math.floor(lvl / 2);
  const extraAttacks = lvl >= 5 ? 2 : 1;
  return {
    level: lvl,
    prof: rule.prof,
    slotCount: rule.slots,
    slotLevel: rule.slotLevel,
    invocations: rule.invocations,
    cantrips: rule.cantrips,
    spellsKnown: rule.spellsKnown,
    arcanum: rule.arcanum,
    smiteDice,
    eldritchBeams,
    cantripDiceCount,
    agathysHP,
    spectreTempHP,
    extraAttacks
  };
}

function getMod(score) {
  return Math.floor((Number(score) - 10) / 2);
}

