// 9. ESTADÍSTICAS EDITABLES (FUE, DES, CON, INT, SAB, CAR) CON BOTONES + Y -
// ============================================================================
function renderStatsGrid(prog) {
  const hasResilientCon = Array.isArray(character.combat_state?.feats) && character.combat_state.feats.includes('resilient_con');
  const attrs = [
    { key: 'str', label: 'Fuerza (FUE)', saveProf: false },
    { key: 'dex', label: 'Destreza (DES)', saveProf: false },
    { key: 'con', label: 'Constitución (CON)', saveProf: hasResilientCon },
    { key: 'int', label: 'Inteligencia (INT)', saveProf: false },
    { key: 'wis', label: 'Sabiduría (SAB)', saveProf: true },
    { key: 'cha', label: 'Carisma (CAR)', saveProf: true }
  ];
  document.getElementById('statsGrid').innerHTML = attrs.map(a => {
    const val = Number(character[a.key]) || 10;
    const mod = getMod(val);
    const save = mod + (a.saveProf ? prog.prof : 0);
    return `
      <div class="bg-slate-950 border ${a.saveProf ? 'border-purple-800/70' : 'border-slate-800'} rounded-xl p-2.5 flex flex-col justify-between">
        <div class="text-[10px] font-bold text-slate-400 uppercase">${a.label}</div>
        <div class="flex items-center justify-center gap-1.5 my-1.5">
          <button onclick="stepAbility('${a.key}', -1)" class="w-6 h-6 rounded bg-slate-800 hover:bg-red-900 text-white font-bold text-xs">-</button>
          <input type="number" min="1" max="30" value="${val}" onchange="updateAbility('${a.key}', this.value)" class="w-12 bg-slate-900 border border-slate-700 rounded text-center font-black text-sm text-white py-0.5 focus:outline-none focus:border-purple-500" />
          <button onclick="stepAbility('${a.key}', 1)" class="w-6 h-6 rounded bg-slate-800 hover:bg-emerald-900 text-white font-bold text-xs">+</button>
        </div>
        <div class="flex items-center justify-between text-[11px] pt-1 border-t border-slate-900">
          <span class="text-slate-400">Mod: <strong class="text-purple-400">${mod >= 0 ? `+${mod}` : mod}</strong></span>
          <span class="text-slate-400">Salv: <strong class="text-emerald-400">${save >= 0 ? `+${save}` : save}</strong></span>
        </div>
      </div>
    `;
  }).join('');
}

async function stepAbility(key, delta) {
  const current = Number(character[key]) || 10;
  await updateAbility(key, Math.min(30, Math.max(1, current + delta)));
}

async function updateAbility(key, val) {
  character[key] = Math.min(30, Math.max(1, Number(val) || 10));
  saveLocalBackup();
  renderAll();
  if (isSupabaseConnected && supabaseClient) {
    await supabaseClient.from('characters').update({ [key]: character[key] }).eq('id', character.id);
  }
}

async function quickAdjustHP(delta) {
  character.hp_current = Math.max(0, Math.min(character.hp_max, (Number(character.hp_current) || 0) + delta));
  document.getElementById('hpCurrent').value = character.hp_current;
  await saveCharacterCore();
}

