function renderCombatLogs() {
  const container = document.getElementById('combatLogList');
  if (logs.length === 0) {
    container.innerHTML = `<div class="text-slate-500">Sin acciones registradas en este encuentro.</div>`;
    return;
  }
  container.innerHTML = logs.map(l => `
    <div class="p-2 rounded bg-slate-950/90 border border-slate-800/80 text-slate-300">
      <span class="text-purple-400 font-bold">[A${l.round_num || 1}]</span> ${l.log_text}
    </div>
  `).join('');
}

async function addCombatLog(text) {
  const roundNum = character?.combat_state?.round || 1;
  const newEntry = { character_id: character.id, round_num: roundNum, log_text: text };
  logs.unshift(newEntry);
  saveLocalBackup();
  renderCombatLogs();
  if (isSupabaseConnected && supabaseClient) {
    await supabaseClient.from('combat_logs').insert([newEntry]);
  }
}

async function clearCombatLogs() {
  logs = [];
  saveLocalBackup();
  renderCombatLogs();
  if (isSupabaseConnected && supabaseClient) {
    await supabaseClient.from('combat_logs').delete().eq('character_id', character.id);
  }
}

function switchTab(tabName) {
  ['combat', 'equipment', 'spells', 'companions'].forEach(t => {
    document.getElementById(`tab-${t}`).classList.toggle('hidden', t !== tabName);
    const btn = document.getElementById(`tabBtn-${t}`);
    if (t === tabName) {
      btn.className = 'px-4 py-1.5 rounded-lg text-sm font-bold bg-purple-700 text-white shadow flex items-center gap-2';
    } else {
      btn.className = 'px-4 py-1.5 rounded-lg text-sm font-semibold text-slate-400 hover:text-white hover:bg-slate-800/60 flex items-center gap-2';
    }
  });
}

function closeModal() {
  document.getElementById('editorModal').classList.add('hidden');
}

